const def=(id,symbol,type,definition,depends_on=[],objects=[],binders=[])=>({id,symbol,type,definition,depends_on,requires:[],binders,objects});
const ds=[
def("D001","Rn","family of Euclidean real normed spaces indexed by natural numbers","For each natural m, Rn(m)=EuclideanSpace ℝ (Fin m), namely real m-tuples with norm (Σ_{h<m}|x_h|²)^(1/2). For m=0 this is the one-point zero vector space.",[],[],[b("m","natural number"),b("x","element of Rn(m)"),b("h","coordinate index less than m")]),
def("D002","ediam","extended diameter of a subset of an emetric space","For an emetric space W and B⊆W, ediam(B)=sup{edist(x,y):x,y∈B} in ℝ≥0∞; the empty supremum is zero.",[],[],[b("W","emetric space"),b("B","subset of W"),b("x","point of B"),b("y","point of B")]),
def("D003","diam","real diameter of a bounded subset of a metric space","For a bounded subset B of a metric space W, diam(B)=sup{dist(x,y):x,y∈B}, with diam(∅)=0. Its cast to ℝ≥0∞ is ediam(B). This notation is used only after boundedness has been established.",["D002"],["ediam"],[b("W","metric space"),b("B","bounded subset of W"),b("x","point of B"),b("y","point of B")]),
def("D004","content","extended-scale unnormalized diameter content","For an emetric space W, B⊆W, real a and r∈ℝ≥0∞, content(a,r,B)= inf_{U:ℕ→Set W} inf_{B⊆⋃i U_i} inf_{∀i ediam(U_i)≤r} Σ'_i sup_{h:U_i nonempty} ediam(U_i)^a. Infima and sums take values in ℝ≥0∞. A failed condition has empty infimum ∞; the supremum over a nonemptiness proof is zero for an empty member. This is exactly BasisObjects.content in basis-registry.json /lean_header.",["D002"],["ediam"],[b("W","emetric space"),b("B","subset of W"),b("a","real exponent"),b("r","extended nonnegative scale"),b("U","sequence of subsets of W"),b("i","natural index"),b("h","proof of nonemptiness of U_i")]),
def("D005","C","positive-real-scale diameter content","For a metric space W, B⊆W, a>0 and δ>0, C^a_δ(B)=content(a,ENNReal.ofReal δ,B). Equivalently it is the infimum of Σ_i diam(U_i)^a over countable covers of B by sets of diameter ≤δ, with empty members contributing zero. The equivalence with this real-diameter formulation is proved in N001.",["D003","D004"],["diam","content"],[b("W","metric space"),b("B","subset of W"),b("a","positive real exponent"),b("δ","positive real scale"),b("U","countable family of subsets of W"),b("i","index of the family")]),
def("D006","H","unnormalized Hausdorff measure evaluated on a set","For a Borel emetric space W, B⊆W and real a, H^a(B)=MeasureTheory.Measure.hausdorffMeasure a B. It is the metric outer-measure construction with gauge r↦r^a and no dimensional prefactor, in ℝ≥0∞. For a>0 on metric spaces its equality with sup_{δ>0} C^a_δ(B) is proved in N001.",["D005"],["C"],[b("W","emetric space with its Borel measurable structure"),b("B","subset of W"),b("a","real exponent"),b("r","extended nonnegative number"),b("δ","positive real scale")]),
def("D007","dimH","Hausdorff dimension of a subset of an emetric space","For an emetric space W and B⊆W, dimH(B)=sup{d∈ℝ≥0 : H^d(B)=∞}, interpreted in ℝ≥0∞, using the Borel structure of W. This is Hausdorff dimension and gives dimH(∅)=0. A finite dimension can be represented by its nonnegative real value; we explicitly establish finiteness before doing so.",["D006"],["H"],[b("W","emetric space"),b("B","subset of W"),b("d","nonnegative real exponent")]),
def("D008","I","subset of ℝ","I=[0,1], the closed unit interval in ℝ."),
def("D009","MaxProd","family of metric spaces","For a metric space W, MaxProd(W)=W×ℝ with distance max(dist(x,y),|t-u|) between (x,t) and (y,u). For real normed W this is its usual maximum product norm.",[],[],[b("W","metric space"),b("x","point of W"),b("y","point of W"),b("t","real number"),b("u","real number")]),
def("D010","L2Prod","family of real normed spaces indexed by natural numbers","L2Prod(m)=WithLp 2 (Rn(m)×ℝ), with the library L² product norm and its induced metric.",["D001"],["Rn"],[b("m","natural number")]),
def("D011","euclideanLift","family of maps MaxProd(Rn(m))→L2Prod(m)","For every natural m, euclideanLift m=WithLp.toLp 2 on Rn(m)×ℝ; it is the identity on underlying pairs. This preserves the exact definition in the frozen basis header; its dimension-preserving property is supplied only by E001.",["D001","D009","D010"],["Rn","MaxProd","L2Prod"],[b("m","natural number")]),
def("D012","j","family of coordinate concatenation maps L2Prod(m)→Rn(m+1)","For each natural m, j(m)(p) is the (m+1)-tuple whose first m coordinates are those of p.fst and whose last coordinate is p.snd. This defines a total map; its isometry and inverse are proved in N007.",["D001","D010"],["Rn","L2Prod"],[b("m","natural number"),b("p","point of L2Prod(m)")]),
def("D013","F","subset of MaxProd(Rn(n))","F=E×I, regarded during the cover argument as a subset of MaxProd(Rn(n)).",["D001","D008","D009"],["E","I","MaxProd","Rn","n"]),
def("D014","D","extended nonnegative real number","D=dimH(E), with E in its original Euclidean Rn(n) metric.",["D001","D007"],["dimH","E","Rn","n"]),
def("D015","T","extended nonnegative real number","T=dimH(F), using the maximum product metric.",["D007","D013"],["dimH","F"]),
def("D016","G","subset of Euclidean Rn(n+1)","G consists of coordinate concatenations (x_0,…,x_{n-1},t) with x∈E and t∈I. This is exactly E×[0,1] under the original target's specified identification with Euclidean ℝ^(n+1).",["D001","D008"],["Rn","n","E","I"],[b("x","point of E"),b("t","point of I")]),
def("D017","volume","Lebesgue measure on the real line","volume denotes Lebesgue measure on the Borel measurable space ℝ, with values in ℝ≥0∞."),
def("D018","indicator","set indicator with a zero outside branch","For a set B⊆W and function f:W→ℝ≥0∞, indicator(B,f)(t)=f(t) for t∈B and 0 otherwise. We write 1_B(t)c for indicator(B,constant c)(t), including c=∞; this uses a zero branch outside B.",[],[],[b("W","type"),b("B","subset of W"),b("f","function W→ℝ≥0∞"),b("t","point of W"),b("c","extended nonnegative constant")]),
def("D019","lintegral","nonnegative lower integral","lintegral(μ,f)=∫⁻ t,f(t)∂μ is the supremum of the integrals of nonnegative measurable simple functions below f, for a measure μ on a measurable space W and f:W→ℝ≥0∞. No finiteness of the value is implicit.",[],[],[b("W","measurable space"),b("μ","measure on W"),b("f","function W→ℝ≥0∞"),b("t","point of W")])
];
