addM("M006","For every emetric space W and sets A,B⊆W, A⊆B implies dimH(A)≤dimH(B).",["W is an emetric space.","A⊆B."],[b("W","emetric space"),aset,b("B","subset of W")],["D007"],["W","A","B","dimH"]);
addM("M007","For every finite-dimensional real normed vector space W, dimH(univ W)=finrank ℝ W, with finrank cast into ℝ≥0∞.",["W is a real normed additive commutative group and real normed vector space.","W is finite dimensional over ℝ."],[b("W","finite-dimensional real normed vector space")],["D007"],["W","dimH"]);
addM("M008","For every pair of emetric spaces W,Z, isometry f:W→Z and A⊆W, dimH(f '' A)=dimH(A). Isometry means preservation of extended distances of every pair of points.",["W and Z are emetric spaces.","f preserves all extended distances."],[b("W","emetric space"),b("Z","emetric space"),b("f","map W→Z"),aset],["D007"],["W","Z","f","A","dimH"]);
addM("M009","For every pair of real endpoints a,b, volume([a,b])=ENNReal.ofReal(b-a), including reversed and degenerate intervals.",[],[b("a","real number"),b("b","real number")],["D017"],["a","b","volume"]);
addM("M010","For a measurable space W, measure μ, countable index type J, and f:J→W→ℝ≥0∞, if each f_i is μ-almost-everywhere measurable, then lintegral(μ, t↦Σ'_i f_i(t))=Σ'_i lintegral(μ,f_i). No integrability or finiteness assumption is required.",["W is a measurable space and μ is a measure on W.","J is countable.","Every f_i is μ-almost-everywhere measurable."],[b("W","measurable space"),b("μ","measure on W"),b("J","countable index type"),b("f","family J→W→ℝ≥0∞"),b("i","element of J"),b("t","point of W")],["D019"],["W","μ","J","f","i","t","lintegral"]);
addM("M011","For a measurable space W, measure μ and functions f,g:W→ℝ≥0∞, if f(t)≤g(t) for every t, then lintegral(μ,f)≤lintegral(μ,g). No measurability condition on f or g is needed.",["W is a measurable space and μ is a measure on W.","f≤g pointwise."],[b("W","measurable space"),b("μ","measure on W"),b("f","function W→ℝ≥0∞"),b("g","function W→ℝ≥0∞"),b("t","point of W")],["D019"],["W","μ","f","g","t","lintegral"]);
addM("M012","For a measurable space W, measure μ, measurable set B⊆W and c∈ℝ≥0∞, lintegral(μ,indicator(B,constant c))=c·μ(B).",["W is a measurable space and μ is a measure on W.","B is measurable."],[b("W","measurable space"),b("μ","measure on W"),b("B","measurable subset of W"),b("c","extended nonnegative real")],["D018","D019"],["W","μ","B","c","indicator","lintegral"]);
